# D4 transforms on 6x6 hole masks and score over all translations? centered dims same; just D4
import numpy as np
cmasks={'7':{(1,1),(4,4)},'1':{(1,1),(1,4),(4,4)},'3':{(1,1),(1,4),(4,1),(4,4)},'5':{(1,1)}}
def d4(m,n=6):
 a=np.zeros((n,n),int)
 for r,c in m:a[r,c]=1
 arrs=[]
 for k in range(4):
  b=np.rot90(a,k)
  arrs += [b,np.fliplr(b)]
 return [{(r,c) for r in range(n) for c in range(n) if x[r,c]} for x in arrs]
for c,m in cmasks.items():
 print('\n',c)
 for p,s in pattern_masks.items():
  scores=[]
  for t in d4(s):
   # intersection / canvas anomalies, and Jaccard
   scores.append((len(m&t),len(m&t)/len(m),len(m&t)/len(m|t)))
  print(p, max(scores))

# build demo2 hole masks in 5x5 inner coordinates by manually read input panels and motifs
# masks outer 7x7 panel coords translate subtract 1
Dcan={'4':{(2,2),(2,4),(3,3),(4,2),(4,4)},'9':set(),'2':{(2,2),(2,4),(4,2)},'3':{(2,4),(4,2)},'5':{(2,2),(2,4),(4,2),(4,4)},'7':{(2,4)}}
Dcan={k:{(r-1,c-1) for r,c in s} for k,s in Dcan.items()}
Dpat={
 '2':{(1,1),(1,3),(2,2),(3,1),(3,3)},
 '8':set(),
 '0':{(1,3),(2,2),(3,1)},
 '7':{(1,1),(1,3),(2,1),(2,3),(3,1),(3,3)},
 '6':{(1,1),(1,3),(3,1),(3,3)},
 '3':{(1,1),(1,2),(1,3),(2,1),(2,2),(2,3),(3,1),(3,2),(3,3)}
}
actual={'4':'2','9':'8','2':'0','3':'7','5':'6','7':'3'}
for c,p in actual.items(): print(c,p, 'hamming',len(Dcan[c]^Dpat[p]),'extra C',len(Dcan[c]-Dpat[p]),'extra P',len(Dpat[p]-Dcan[c]))
# compute hamming assignment optimum
import itertools
cs=list(Dcan); ps=list(Dpat)
vals=[]
for perm in itertools.permutations(ps):
 cost=sum(len(Dcan[c]^Dpat[p]) for c,p in zip(cs,perm))
 if cost<=min(x[0] for x in vals) if vals else True: pass
 vals.append((cost,perm))
mincost=min(x[0] for x in vals)
print('min',mincost,'actual',sum(len(Dcan[c]^Dpat[p]) for c,p in actual.items()))
print([p for cost,p in vals if cost==mincost][:10])

for metric in ['hamming','jaccard']:
 vals=[]
 for perm in itertools.permutations(pattern_masks):
  score=0
  for c,p in zip(cmasks,perm):
   a=cmasks[c];b=pattern_masks[p]
   if metric=='hamming': score+=len(a^b)
   else: score += len(a&b)/len(a|b) if a|b else 1
  vals.append((score,perm))
 print(metric, (min if metric=='hamming' else max)(x[0] for x in vals), sorted(vals,reverse=metric=='jaccard')[:5])

